const docId = $input.item.json.id;
const binary = $('Normalize Intake').first().binary;
return {
  json: { doc_id: docId },
  binary: binary,
};

const formData = $('Normalize Intake').first().json;
const jd = $('Get Job Description').first().json;
const combined = $('Combine JD and CV').first().json;
const parsed = $input.first().json;
const profile = parsed.candidate_profile || {};
const evalr = parsed.evaluation || {};
const intakeTs = $('Stamp Intake Time').first().json.intake_timestamp || Date.now();

const toStr = (arr) => (arr || []).join(', ');

const submission_id = 'CV-' + Date.now();
const timestamp = new Date().toISOString();

const requiredScore = evalr.required_skills_score || 0;
const overall = evalr.overall_score || 0;

let recommendation;
if (requiredScore < 40) recommendation = 'Do Not Proceed';
else if (overall >= 75) recommendation = 'Strong Interview';
else if (overall >= 60) recommendation = 'Interview';
else if (overall >= 45) recommendation = 'Borderline';
else recommendation = 'Do Not Proceed';

const decision = (recommendation === 'Strong Interview' || recommendation === 'Interview')
  ? 'shortlisted'
  : recommendation === 'Borderline' ? 'borderline' : 'rejected';

const gapsCount = (evalr.critical_gaps || []).length;
const risk_level = gapsCount >= 3 ? 'High' : gapsCount >= 1 ? 'Medium' : 'Low';

const PRICING = { in: 3.0, out: 15.0 }; // Claude Sonnet 4.5, USD per 1M tokens
const PROMPT_OVERHEAD_TOKENS = 2000;
const estTokens = (s) => Math.round(String(s || '').length / 4);
const cvText = combined.text || '';
const jdStr = JSON.stringify(jd);
const outStr = JSON.stringify(parsed);
const inTok = estTokens(cvText) + estTokens(jdStr) + PROMPT_OVERHEAD_TOKENS;
const outTok = estTokens(outStr);
const cost_usd = parseFloat(((inTok / 1_000_000) * PRICING.in + (outTok / 1_000_000) * PRICING.out).toFixed(6));

return {
  json: {
    submission_id, timestamp,
    applied_job_id: formData.applied_job_id || '',
    applied_job_title: jd.title || '',
    candidate_name: formData.candidate_name || '',
    candidate_email: formData.candidate_email || '',
    role_category: evalr.role_category || '',
    ats_score: overall,
    required_skills_score: requiredScore,
    confidence: evalr.confidence || '',
    skills_reasoning: evalr.skills_reasoning || '',
    experience_reasoning: evalr.experience_reasoning || '',
    domain_reasoning: evalr.domain_reasoning || '',
    ats_summary: evalr.summary || '',
    critical_gaps: toStr(evalr.critical_gaps),
    strength_signals: toStr(evalr.strength_signals),
    risk_level,
    recommendation,
    upgrade_applied: false,
    final_summary: evalr.summary || '',
    decision, review_status: 'pending', cv_drive_link: '', email_sent: false,
    processing_time_ms: Date.now() - intakeTs,
    cost_usd,
    recruiter_model: 'anthropic/claude-sonnet-4.5',
    fields_used: 'skills, experience, domain, nice_to_have',
  },
  binary: $('Normalize Intake').first().binary,
};

const webhook = $('CV Intake Webhook').first();
const data = webhook.json;
const binary = webhook.binary;

const cvFile = binary?.cv_file || {};

return {
  json: {
    candidate_name: data?.candidate_name || '',
    candidate_email: data?.candidate_email || '',
    applied_job_id: data?.applied_job_id || '',
    intake_timestamp: $('Stamp Intake Time').first().json.intake_timestamp,
    source: 'webhook',
    cv_file: {
      fileName: cvFile.fileName || cvFile.filename || 'cv_upload',
      mimetype: cvFile.mimeType || cvFile.mimetype || '',
      fileSize: cvFile.fileSize || 0,
    },
  },
  binary,
};

const raw = $input.first().json.output || '';

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      parsed = { candidate_profile: null, evaluation: null, parse_error: e2.message };
    }
  } else {
    parsed = { candidate_profile: null, evaluation: null, parse_error: e.message };
  }
}

return {
  json: parsed,
  binary: $('Normalize Intake').first().binary,
};
